import { Text } from "@react-email/components";
import { AlertBox, CodeBlock, PrimaryButton, RepoFooter, TerminalHeader, VrekoLayout } from "../../components";
import type { MagicLinkContext } from "../../contexts";
import { MagicLinkContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function MagicLink({ loginUrl, expiresInMinutes, ipAddress, userAgent }: MagicLinkContext) {
	return (
		<VrekoLayout title="Sign in to Vreko" preheader="Your magic link to sign in">
			<TerminalHeader status="online" />

			<Text style={{ fontSize: "18px", marginBottom: "24px", color: "#FAFAFA" }}>Sign in to Vreko</Text>

			<AlertBox type="info">Click the button below to securely sign in to your Vreko account.</AlertBox>

			<PrimaryButton href={loginUrl}>Sign In</PrimaryButton>

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "16px" }}>
				This magic link expires in {expiresInMinutes} minutes.
			</Text>

			<Text
				style={{
					fontSize: "14px",
					marginTop: "32px",
					marginBottom: "8px",
					color: "#A1A1AA",
				}}
			>
				Request details:
			</Text>

			<CodeBlock code={`IP Address: ${ipAddress}\nUser Agent: ${userAgent}`} />

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "24px" }}>
				If you didn't request this sign-in link, you can safely ignore this email.
			</Text>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const MagicLinkTemplate: EmailTemplate<MagicLinkContext> = {
	id: "auth.magic-link",
	category: "authentication",
	subject: () => "Sign in to Vreko",
	component: MagicLink,
	previewProps: {
		loginUrl: "https://vreko.dev/auth/verify?token=xyz789",
		expiresInMinutes: 15,
		ipAddress: "192.168.1.1",
		userAgent: "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)",
	},
	schema: MagicLinkContextSchema,
};
