import { Heading, Link, Section, Text } from "@react-email/components";
import { RepoFooter } from "../../components/layouts/RepoFooter";
import { TerminalHeader } from "../../components/layouts/TerminalHeader";
import { VrekoLayout } from "../../components/layouts/VrekoLayout";
import { AlertBox } from "../../components/primitives/AlertBox";
import { PrimaryButton } from "../../components/primitives/PrimaryButton";
import { StatRow } from "../../components/primitives/StatRow";
import { type NiceSaveContext, NiceSaveContextSchema } from "../../contexts";
import { emailTheme } from "../../theme";
import type { EmailTemplate } from "../../types";

export function NiceSave({
	firstName,
	filesRecovered,
	linesOfCode,
	timeSavedMinutes,
	sessionTime,
	restoreTime,
	aiToolDetected,
	dashboardUrl,
	twitterShareUrl,
}: NiceSaveContext) {
	const timeSavedText =
		timeSavedMinutes >= 60
			? `${Math.floor(timeSavedMinutes / 60)}h ${timeSavedMinutes % 60}m`
			: `${timeSavedMinutes}m`;

	return (
		<VrekoLayout
			title="Nice Save! Your Code is Safe"
			preheader={`You just recovered ${filesRecovered} file${filesRecovered !== 1 ? "s" : ""} with Vreko`}
		>
			<TerminalHeader status="online" />

			<Section style={{ padding: "32px 24px" }}>
				<Heading
					style={{
						margin: "0 0 16px 0",
						fontSize: "28px",
						fontWeight: "700",
						color: emailTheme.colors.primary,
						fontFamily: emailTheme.fonts.mono,
						textAlign: "center",
					}}
				>
					🎉 Nice Save!
				</Heading>

				<Text
					style={{
						margin: "0 0 24px 0",
						fontSize: "16px",
						lineHeight: "24px",
						color: emailTheme.colors.textSecondary,
						fontFamily: emailTheme.fonts.sans,
						textAlign: "center",
					}}
				>
					Hey {firstName}, you just recovered your code with Vreko. That's what we're here for!
				</Text>

				<AlertBox type="success">
					<span>Your restore completed successfully. Your code is back to its pre-AI state.</span>
				</AlertBox>

				{/* Recovery Stats */}
				<Section
					style={{
						margin: "32px 0",
						padding: "24px",
						backgroundColor: emailTheme.colors.surfaceSubtle,
						border: `1px solid ${emailTheme.colors.border}`,
						borderRadius: "8px",
					}}
				>
					<Heading
						style={{
							margin: "0 0 16px 0",
							fontSize: "18px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.mono,
						}}
					>
						Recovery Summary
					</Heading>

					<StatRow label="Files Recovered" value={filesRecovered.toString()} icon="📁" />
					<StatRow label="Lines of Code" value={linesOfCode.toLocaleString()} icon="📝" />
					<StatRow label="Time Saved" value={timeSavedText} icon="⏱️" />
					{aiToolDetected && <StatRow label="AI Tool Detected" value={aiToolDetected} icon="🤖" />}
				</Section>

				{/* Timeline */}
				<Section
					style={{
						margin: "24px 0",
						padding: "20px",
						backgroundColor: emailTheme.colors.backgroundSecondary,
						border: `1px solid ${emailTheme.colors.border}`,
						borderRadius: "8px",
					}}
				>
					<Text
						style={{
							margin: "0 0 12px 0",
							fontSize: "14px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.mono,
						}}
					>
						📸 Session started: {sessionTime}
					</Text>
					<Text
						style={{
							margin: 0,
							fontSize: "14px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.mono,
						}}
					>
						⏪ Restored at: {restoreTime}
					</Text>
				</Section>

				{/* What Happened */}
				<Section style={{ margin: "32px 0" }}>
					<Heading
						style={{
							margin: "0 0 16px 0",
							fontSize: "18px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.mono,
						}}
					>
						What Just Happened?
					</Heading>

					<Text
						style={{
							margin: "0 0 16px 0",
							fontSize: "14px",
							lineHeight: "22px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Vreko's AutoDecisionEngine detected changes that needed protection and automatically tracked
						your session. When you needed to recover, we had your back.
					</Text>

					<Text
						style={{
							margin: 0,
							fontSize: "14px",
							lineHeight: "22px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Without Vreko, you might have spent {timeSavedText} manually reconstructing your code or digging
						through git history. Instead, one click and you're back.
					</Text>
				</Section>

				{/* CTA Buttons */}
				<Section style={{ textAlign: "center", margin: "32px 0" }}>
					<PrimaryButton href={dashboardUrl}>View in Dashboard</PrimaryButton>

					{twitterShareUrl && (
						<Text
							style={{
								margin: "16px 0 0 0",
								fontSize: "14px",
								color: emailTheme.colors.textSecondary,
							}}
						>
							<Link
								href={twitterShareUrl}
								style={{
									color: emailTheme.colors.primary,
									textDecoration: "none",
								}}
							>
								Share your save on Twitter →
							</Link>
						</Text>
					)}
				</Section>

				{/* Pro Tip */}
				<Section
					style={{
						margin: "32px 0 0 0",
						padding: "20px",
						backgroundColor: emailTheme.colors.surfaceSubtle,
						border: `1px solid ${emailTheme.colors.primary}`,
						borderRadius: "8px",
					}}
				>
					<Text
						style={{
							margin: 0,
							fontSize: "14px",
							lineHeight: "20px",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						<strong style={{ color: emailTheme.colors.primary }}>💡 Pro Tip:</strong> Vreko learns from your
						workflow. The more you use it, the smarter it gets at predicting when you'll need protection.
					</Text>
				</Section>
			</Section>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const NiceSaveTemplate: EmailTemplate<NiceSaveContext> = {
	id: "product.nice-save",
	category: "product",
	subject: (ctx) => `🎉 Nice Save, ${ctx.firstName}! You just recovered ${ctx.filesRecovered} files`,
	component: NiceSave,
	previewProps: {
		firstName: "Alex",
		filesRecovered: 3,
		linesOfCode: 247,
		timeSavedMinutes: 45,
		sessionTime: "Today at 2:34 PM",
		restoreTime: "Today at 3:12 PM",
		aiToolDetected: "Claude Code",
		dashboardUrl: "https://vreko.dev/dashboard/restores",
		twitterShareUrl:
			"https://twitter.com/intent/tweet?text=Just%20recovered%20247%20lines%20of%20code%20with%20@vrekodev%20%F0%9F%8E%89",
	},
	schema: NiceSaveContextSchema,
};
