// @deprecated  -  replaced by canonical Vreko template.
import { Text } from "@react-email/components";
import { Badge, BodyText, PrimaryButton, TerminalBlock, VrekoEmailShell } from "../../components";
import type { WelcomeContext } from "../../contexts";
import { WelcomeContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function Welcome({
	firstName,
	planName,
	planFeatures,
	dashboardUrl,
	docsUrl,
	pioneerTier,
	pioneerPoints,
}: WelcomeContext) {
	const greeting = firstName ? `${firstName}, we received your request.` : "We received your request.";
	const previewText = `Welcome to Vreko${pioneerTier ? ` · Pioneer ${pioneerTier}` : ""}`;

	return (
		<VrekoEmailShell title={`Welcome to Vreko, ${firstName}`} previewText={previewText}>
			<Badge label="Pioneer Cohort" />
			<Text
				style={{
					margin: "0 0 20px 0",
					fontFamily: "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif",
					fontSize: "20px",
					lineHeight: "1.35",
					fontWeight: 600,
					color: "#FFFFFF",
					letterSpacing: "-0.01em",
				}}
			>
				{greeting}
			</Text>
			<BodyText>
				You're on the <strong>{planName}</strong> plan. Vreko is set up to watch your codebase locally, record
				what actually breaks, and write those signals back into AGENTS.md for the next session.
			</BodyText>
			<BodyText mb={24}>
				No code leaves your machine. Intelligence compounds with each session, and your docs stay current as the
				daemon learns your workspace.
			</BodyText>
			<TerminalBlock cursor>
				{[
					`plan: ${planName}`,
					pioneerTier ? `pioneer tier: ${pioneerTier}` : null,
					pioneerPoints !== undefined ? `pioneer points: ${pioneerPoints}` : null,
				]
					.filter(Boolean)
					.join("\n")}
			</TerminalBlock>
			{planFeatures.length > 0 ? (
				<BodyText mt={24} mb={16}>
					{planFeatures.slice(0, 3).join(" · ")}
				</BodyText>
			) : null}
			<PrimaryButton href={dashboardUrl}>Open Dashboard</PrimaryButton>
			<BodyText mt={8} mb={0}>
				Need the setup guide?{" "}
				<a href={docsUrl} style={{ color: "#4ADE80", textDecoration: "none" }}>
					Read the docs →
				</a>
			</BodyText>
		</VrekoEmailShell>
	);
}

export const WelcomeTemplate: EmailTemplate<WelcomeContext> = {
	id: "product.welcome",
	category: "product",
	subject: (ctx) => `Welcome to Vreko, ${ctx.firstName}`,
	component: Welcome,
	previewProps: {
		firstName: "Alex",
		planName: "Developer",
		planFeatures: ["Unlimited session history", "GitHub integration", "Team collaboration"],
		dashboardUrl: "https://vreko.dev/dashboard",
		docsUrl: "https://docs.vreko.dev/getting-started",
		pioneerTier: "Explorer",
		pioneerPoints: 250,
	},
	schema: WelcomeContextSchema,
};

export default Welcome;
