import type React from "react";
import { VrekoEmailShell } from "../VrekoEmailShell";

export interface VrekoLayoutProps {
	title: string;
	preheader?: string;
	children: React.ReactNode;
}

export function VrekoLayout({ title, preheader, children }: VrekoLayoutProps) {
	return (
		<VrekoEmailShell title={title} previewText={preheader ?? title}>
			{children}
		</VrekoEmailShell>
	);
}

export default VrekoLayout;
