import { z } from "zod";

/**
 * Template Context Types with Zod Schemas
 * Type-safe email template contexts
 */

// Verify Email
export const VerifyEmailContextSchema = z.object({
	verificationUrl: z.string().url(),
	expiresInMinutes: z.number().int().positive(),
});

export type VerifyEmailContext = z.infer<typeof VerifyEmailContextSchema>;

// Magic Link
export const MagicLinkContextSchema = z.object({
	loginUrl: z.string().url(),
	expiresInMinutes: z.number().int().positive(),
	ipAddress: z.string(),
	userAgent: z.string(),
});

export type MagicLinkContext = z.infer<typeof MagicLinkContextSchema>;

// Reset Password
export const ResetPasswordContextSchema = z.object({
	resetUrl: z.string().url(),
	expiresInMinutes: z.number().int().positive(),
	requestedFrom: z.object({
		ipAddress: z.string(),
		location: z.string().optional(),
	}),
});

export type ResetPasswordContext = z.infer<typeof ResetPasswordContextSchema>;

// New Device Login
export const NewDeviceLoginContextSchema = z.object({
	deviceName: z.string(),
	location: z.string(),
	ipAddress: z.string(),
	timestamp: z.date(),
	approveUrl: z.string().url(),
	denyUrl: z.string().url(),
});

export type NewDeviceLoginContext = z.infer<typeof NewDeviceLoginContextSchema>;

// Welcome Email
export const WelcomeContextSchema = z.object({
	firstName: z.string(),
	planName: z.string(),
	planFeatures: z.array(z.string()),
	dashboardUrl: z.string().url(),
	docsUrl: z.string().url(),
	pioneerTier: z.string().optional(),
	pioneerPoints: z.number().int().nonnegative().optional(),
});

export type WelcomeContext = z.infer<typeof WelcomeContextSchema>;

// Pioneer Milestone
export const PioneerMilestoneContextSchema = z.object({
	firstName: z.string(),
	oldTier: z.string(),
	newTier: z.string(),
	pointsEarned: z.number().int().nonnegative(),
	totalPoints: z.number().int().nonnegative(),
	nextTierName: z.string().optional(),
	pointsToNextTier: z.number().int().nonnegative().optional(),
	unlockedPerks: z.array(
		z.object({
			icon: z.string(),
			name: z.string(),
			description: z.string(),
		}),
	),
	dashboardUrl: z.string().url(),
});

export type PioneerMilestoneContext = z.infer<typeof PioneerMilestoneContextSchema>;

// Weekly Digest
export const WeeklyDigestContextSchema = z.object({
	firstName: z.string(),
	weekStartDate: z.string(),
	weekEndDate: z.string(),
	stats: z.object({
		totalSnapshots: z.number().int().nonnegative(),
		testsPassed: z.number().int().nonnegative(),
		regressionsCaught: z.number().int().nonnegative(),
		activeProjects: z.number().int().nonnegative(),
		activeMembers: z.number().int().nonnegative(),
		pioneerPointsEarned: z.number().int().nonnegative(),
		comparisonToPreviousWeek: z.number().optional(),
	}),
	highlights: z.array(
		z.object({
			icon: z.string(),
			title: z.string(),
			description: z.string(),
		}),
	),
	dashboardUrl: z.string().url(),
});

export type WeeklyDigestContext = z.infer<typeof WeeklyDigestContextSchema>;

// System Alert
export const SystemAlertContextSchema = z.object({
	tier: z.enum(["free", "pro"]),
	repositoryName: z.string().min(1),
	filePath: z.string().min(1),
	score: z.number().min(0).max(1),
	aiSessionCount: z.number().int().nonnegative(),
	riskLevel: z.enum(["LOW", "MEDIUM", "HIGH", "CRITICAL"]),
	actionUrl: z.string().url().optional(),
	actionLabel: z.string().min(1).optional(),
});

export type SystemAlertContext = z.infer<typeof SystemAlertContextSchema>;

// Invoice Receipt
export const InvoiceReceiptContextSchema = z.object({
	amount: z.number().positive(),
	currency: z.string(),
	date: z.date(),
	invoiceUrl: z.string().url(),
	planName: z.string(),
});

export type InvoiceReceiptContext = z.infer<typeof InvoiceReceiptContextSchema>;

// Nice Save (First Restore Celebration)
export const NiceSaveContextSchema = z.object({
	firstName: z.string(),
	filesRecovered: z.number().int().positive(),
	linesOfCode: z.number().int().nonnegative(),
	timeSavedMinutes: z.number().int().nonnegative(),
	sessionTime: z.string(),
	restoreTime: z.string(),
	aiToolDetected: z.string().optional(),
	dashboardUrl: z.string().url(),
	twitterShareUrl: z.string().url().optional(),
});

export type NiceSaveContext = z.infer<typeof NiceSaveContextSchema>;

// Install Nudge (Day 1 Extension Reminder)
export const InstallNudgeContextSchema = z.object({
	firstName: z.string(),
	signupDate: z.string(),
	extensionUrl: z.string().url(),
	docsUrl: z.string().url(),
	dashboardUrl: z.string().url(),
});

export type InstallNudgeContext = z.infer<typeof InstallNudgeContextSchema>;

// Pioneer Intro (Day 7 Engaged Users)
export const PioneerIntroContextSchema = z.object({
	firstName: z.string(),
	currentTier: z.string(),
	currentPoints: z.number().int().nonnegative(),
	nextTierName: z.string().optional(),
	pointsToNextTier: z.number().int().nonnegative().optional(),
	sessionsCompleted: z.number().int().nonnegative(),
	restoresCompleted: z.number().int().nonnegative(),
	daysActive: z.number().int().positive(),
	pioneerDashboardUrl: z.string().url(),
	referralUrl: z.string().url().optional(),
});

export type PioneerIntroContext = z.infer<typeof PioneerIntroContextSchema>;

// We Miss You (14 Days Inactive)
export const WeMissYouContextSchema = z.object({
	firstName: z.string(),
	lastActiveDate: z.string(),
	daysInactive: z.number().int().positive(),
	totalSessions: z.number().int().nonnegative(),
	totalTimelineRestores: z.number().int().nonnegative(),
	pioneerTier: z.string().optional(),
	pioneerPoints: z.number().int().nonnegative().optional(),
	dashboardUrl: z.string().url(),
	extensionUrl: z.string().url(),
	feedbackUrl: z.string().url(),
});

export type WeMissYouContext = z.infer<typeof WeMissYouContextSchema>;

// Cohort Invite (Pioneer accept flow — send invite code to accepted applicant)
export const CohortInviteContextSchema = z.object({
	email: z.string().email(),
	code: z.string().min(1),
	cohort: z.number().int().positive(),
});

export type CohortInviteContext = z.infer<typeof CohortInviteContextSchema>;
