import { Text } from "@react-email/components";
import { AlertBox, CodeBlock, PrimaryButton, RepoFooter, TerminalHeader, VrekoLayout } from "../../components";
import type { NewDeviceLoginContext } from "../../contexts";
import { NewDeviceLoginContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function NewDeviceLogin({
	deviceName,
	location,
	ipAddress,
	timestamp,
	approveUrl,
	denyUrl,
}: NewDeviceLoginContext) {
	return (
		<VrekoLayout title="New device sign-in" preheader="New sign-in detected on your Vreko account">
			<TerminalHeader status="processing" />

			<Text style={{ fontSize: "18px", marginBottom: "24px", color: "#FAFAFA" }}>
				New Device Sign-In Detected
			</Text>

			<AlertBox type="warning">We detected a sign-in to your Vreko account from a new device.</AlertBox>

			<Text
				style={{
					fontSize: "14px",
					marginTop: "24px",
					marginBottom: "8px",
					color: "#A1A1AA",
				}}
			>
				Sign-in details:
			</Text>

			<CodeBlock
				code={`Device: ${deviceName}\nLocation: ${location}\nIP Address: ${ipAddress}\nTime: ${timestamp.toLocaleString()}`}
			/>

			<Text style={{ fontSize: "16px", marginTop: "32px", color: "#FAFAFA" }}>Was this you?</Text>

			<PrimaryButton href={approveUrl}>Yes, this was me</PrimaryButton>

			<Text style={{ marginTop: "16px", fontSize: "14px", color: "#A1A1AA" }}>
				If this wasn't you,{" "}
				<a href={denyUrl} style={{ color: "#EF4444", textDecoration: "underline" }}>
					deny this sign-in
				</a>{" "}
				and secure your account immediately.
			</Text>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const NewDeviceLoginTemplate: EmailTemplate<NewDeviceLoginContext> = {
	id: "auth.new-device-login",
	category: "authentication",
	subject: () => "New device sign-in detected",
	component: NewDeviceLogin,
	previewProps: {
		deviceName: "MacBook Pro (Chrome)",
		location: "San Francisco, CA",
		ipAddress: "192.168.1.1",
		timestamp: new Date(),
		approveUrl: "https://vreko.dev/security/approve?token=ghi789",
		denyUrl: "https://vreko.dev/security/deny?token=ghi789",
	},
	schema: NewDeviceLoginContextSchema,
};
