import { render } from "@react-email/render";
import type { CohortInviteContext } from "../contexts";
import { sendEmail } from "../resend";
import { CohortInvite } from "../templates/product/CohortInvite";

export type CohortInviteInput = CohortInviteContext;

/**
 * Send a cohort invite email to an accepted pioneer applicant.
 *
 * Renders the CohortInvite template to HTML and sends it via Resend.
 * Throws on Resend error — caller handles it.
 */
export async function sendCohortInviteEmail(input: CohortInviteInput): Promise<void> {
	const html = await render(<CohortInvite {...input} />);

	const result = await sendEmail({
		from: "Vreko <q@vreko.dev>",
		to: input.email,
		subject: "You're in — here's your Vreko Pioneer access code",
		html,
	});

	if (result.error) {
		throw new Error(`Resend error sending cohort invite to ${input.email}: ${result.error.message}`);
	}
}
