// @deprecated  -  replaced by canonical Vreko template.
import { Section, Text } from "@react-email/components";
import { Badge, BodyText, Headline, PrimaryButton, StatRow, TerminalBlock, VrekoEmailShell } from "../../components";
import { type WeeklyDigestContext, WeeklyDigestContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function WeeklyDigest({
	firstName,
	weekStartDate,
	weekEndDate,
	stats,
	highlights,
	dashboardUrl,
}: WeeklyDigestContext) {
	const previewText = `${stats.totalSnapshots} sessions tracked · ${stats.regressionsCaught} regressions caught`;

	return (
		<VrekoEmailShell title="Your Weekly Vreko Summary" previewText={previewText}>
			<Badge label="PIONEER UPDATE" />
			<Headline>Here&apos;s what changed since your last pulse.</Headline>
			<BodyText>
				Hey {firstName}, here&apos;s your testing activity from {weekStartDate} to {weekEndDate}. This is the
				weekly pulse from the daemon, not a marketing recap.
			</BodyText>

			<TerminalBlock>
				{[
					`sessions tracked: ${stats.totalSnapshots}`,
					`tests passed: ${stats.testsPassed}`,
					`regressions caught: ${stats.regressionsCaught}`,
					`active projects: ${stats.activeProjects}`,
					`active members: ${stats.activeMembers}`,
				].join("\n")}
			</TerminalBlock>

			<Section style={{ margin: "24px 0 0 0" }}>
				<StatRow label="Sessions tracked" value={stats.totalSnapshots} icon="▸" />
				<StatRow label="Tests passed" value={stats.testsPassed} icon="✓" />
				<StatRow label="Regressions caught" value={stats.regressionsCaught} icon="⚑" />
				<StatRow label="Active projects" value={stats.activeProjects} icon="◫" />
				<StatRow label="Team members active" value={stats.activeMembers} icon="●" />
			</Section>

			{stats.pioneerPointsEarned > 0 ? (
				<BodyText mt={24}>Pioneer points earned this week: +{stats.pioneerPointsEarned}.</BodyText>
			) : null}

			{highlights.length > 0 ? (
				<Section style={{ marginTop: "24px" }}>
					<Headline>Weekly highlights</Headline>
					{highlights.map((highlight) => (
						<Section
							key={`${highlight.title}-${highlight.icon}`}
							style={{
								padding: "16px 0",
								borderTop: "1px solid #27272A",
							}}
						>
							<Text
								style={{
									margin: "0 0 6px 0",
									fontFamily:
										"Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif",
									fontSize: "14px",
									fontWeight: 600,
									color: "#FFFFFF",
								}}
							>
								{highlight.icon} {highlight.title}
							</Text>
							<Text
								style={{
									margin: 0,
									fontFamily:
										"Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif",
									fontSize: "13px",
									lineHeight: 1.6,
									color: "#9CA3AF",
								}}
							>
								{highlight.description}
							</Text>
						</Section>
					))}
				</Section>
			) : null}

			<PrimaryButton href={dashboardUrl}>View Full Dashboard</PrimaryButton>
		</VrekoEmailShell>
	);
}

export const WeeklyDigestTemplate: EmailTemplate<WeeklyDigestContext> = {
	id: "product.weekly-digest",
	category: "product",
	subject: (ctx) => `Your Vreko Weekly Summary: ${ctx.stats.totalSnapshots} sessions tracked`,
	component: WeeklyDigest,
	previewProps: {
		firstName: "Alex",
		weekStartDate: "Jan 15",
		weekEndDate: "Jan 21",
		stats: {
			totalSnapshots: 42,
			testsPassed: 38,
			regressionsCaught: 3,
			activeProjects: 5,
			activeMembers: 2,
			pioneerPointsEarned: 25,
			comparisonToPreviousWeek: 18,
		},
		highlights: [
			{
				icon: "NEW",
				title: "agents-audit CLI published to npm",
				description: "One command audits any repo for AI-session fragility and emits a workspace.json.",
			},
		],
		dashboardUrl: "https://vreko.dev/dashboard",
	},
	schema: WeeklyDigestContextSchema,
};

export default WeeklyDigest;
