// @deprecated  -  replaced by canonical Vreko template.
import { Text } from "@react-email/components";
import { Badge, BodyText, Headline, StatRow, TerminalBlock, VrekoEmailShell } from "../../components";
import { type SystemAlertContext, SystemAlertContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function SystemAlert({ tier, repositoryName, filePath, score, aiSessionCount, riskLevel }: SystemAlertContext) {
	const scoreLabel = score.toFixed(2);
	const previewText =
		tier === "free"
			? `${repositoryName} · Pro unlocks the file path`
			: `${repositoryName} · ${filePath} · fragility ${scoreLabel}`;

	return (
		<VrekoEmailShell title={`Vreko intelligence for ${repositoryName}`} previewText={previewText}>
			<Badge label="INTELLIGENCE UPDATE" />
			<Headline>
				{tier === "free"
					? "A fragile file was detected in your workspace."
					: "Vreko flagged a high-risk file in your codebase."}
			</Headline>

			<BodyText>
				{tier === "free"
					? `Vreko found repeated change and rollback patterns in ${repositoryName}.`
					: `Vreko found repeated change and rollback patterns in ${repositoryName}. The exact file path and score are below.`}
			</BodyText>

			<StatRow label="repository" value={repositoryName} />
			<StatRow label="fragility score" value={scoreLabel} icon="●" />
			<StatRow label="AI sessions" value={aiSessionCount} />
			<StatRow label="risk level" value={riskLevel} />

			{tier === "pro" ? (
				<TerminalBlock cursor>
					{`file path: ${filePath}\nscore: ${scoreLabel}\nrisk: ${riskLevel}`}
				</TerminalBlock>
			) : (
				<BodyText mt={24}>
					Upgrade to Pro to reveal the exact file path and get the full intelligence card for this file.
				</BodyText>
			)}

			<BodyText mt={8} mb={0}>
				Questions about this finding?{" "}
				<a href="mailto:pioneer@vreko.dev" style={{ color: "#4ADE80", textDecoration: "none" }}>
					Reply to this email →
				</a>
			</BodyText>

			<Text
				style={{
					margin: "8px 0 0 0",
					fontFamily: "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif",
					fontSize: "12px",
					lineHeight: "1.6",
					color: "#9CA3AF",
				}}
			>
				{tier === "free"
					? "Free tier keeps the file path hidden."
					: "Pro tier includes the full file path and intelligence card."}
			</Text>
		</VrekoEmailShell>
	);
}

export const SystemAlertTemplate: EmailTemplate<SystemAlertContext> = {
	id: "product.system-alert",
	category: "product",
	subject: (ctx) =>
		ctx.tier === "free"
			? `Vreko found a fragile file in ${ctx.repositoryName}`
			: `Vreko flagged ${ctx.filePath} in ${ctx.repositoryName}`,
	component: SystemAlert,
	previewProps: {
		tier: "pro",
		repositoryName: "marcelle/vreko-web",
		filePath: "apps/console/lib/intelligence/projection.ts",
		score: 0.87,
		aiSessionCount: 12,
		riskLevel: "HIGH",
	},
	schema: SystemAlertContextSchema,
};

export default SystemAlert;
