import { config } from "@vreko/config/server";
// biome-ignore lint/suspicious/noExplicitAny: plans shape is complex and varies by config version
const plans = config.payments.plans;
function getActivePlanFromPurchases(purchases) {
    const subscriptionPurchase = purchases?.find((purchase) => purchase.type === "SUBSCRIPTION");
    if (subscriptionPurchase) {
        // biome-ignore lint/suspicious/noExplicitAny: plan shape is dynamic
        const planEntry = Object.entries(plans).find(([_key, plan]) => 
        // biome-ignore lint/suspicious/noExplicitAny: plan shape is dynamic
        plan.prices?.some((price) => price.productId === subscriptionPurchase.productId));
        return {
            id: planEntry?.[0],
            // biome-ignore lint/suspicious/noExplicitAny: plan value shape is dynamic
            price: planEntry?.[1]?.prices?.find((price) => price.productId === subscriptionPurchase.productId),
            status: subscriptionPurchase.status,
            purchaseId: subscriptionPurchase.id,
        };
    }
    const oneTimePurchase = purchases?.find((purchase) => purchase.type === "ONE_TIME");
    if (oneTimePurchase) {
        // biome-ignore lint/suspicious/noExplicitAny: plan shape is dynamic
        const planEntry = Object.entries(plans).find(([_key, plan]) => 
        // biome-ignore lint/suspicious/noExplicitAny: plan shape is dynamic
        plan.prices?.some((price) => price.productId === oneTimePurchase.productId));
        return {
            id: planEntry?.[0],
            // biome-ignore lint/suspicious/noExplicitAny: plan value shape is dynamic
            price: planEntry?.[1]?.prices?.find((price) => price.productId === oneTimePurchase.productId),
            status: "active",
            purchaseId: oneTimePurchase.id,
        };
    }
    // biome-ignore lint/suspicious/noExplicitAny: plan shape is dynamic
    const freePlan = Object.entries(plans).find(([_key, plan]) => plan.isFree);
    return freePlan
        ? {
            id: freePlan[0],
            status: "active",
        }
        : null;
}
export function createPurchasesHelper(purchases) {
    const activePlan = getActivePlanFromPurchases(purchases);
    const hasSubscription = (planIds) => {
        // biome-ignore lint/style/noNonNullAssertion: activePlan is verified truthy before this expression
        return !!activePlan && (Array.isArray(planIds) ? planIds.includes(activePlan.id) : planIds === activePlan.id);
    };
    const hasPurchase = (planId) => {
        return !!purchases?.some((purchase) => 
        // biome-ignore lint/suspicious/noExplicitAny: plan value shape is dynamic
        Object.entries(plans).find(([id]) => id === planId)?.[1]?.prices?.some((price) => price.productId === purchase.productId));
    };
    return { activePlan, hasSubscription, hasPurchase };
}
