import { Section, Text } from "@react-email/components";
import type React from "react";
import { VREKO_COLORS, VREKO_FONT_MONO } from "../VrekoEmailShell";

export interface TerminalBlockProps {
	children: React.ReactNode;
	cursor?: boolean;
}

const TERMINAL_BG = "#111827";

const wrapStyle: React.CSSProperties = {
	width: "100%",
	margin: "0 0 24px 0",
	backgroundColor: TERMINAL_BG,
	borderRadius: "8px",
	border: `1px solid ${VREKO_COLORS.border}`,
};

const cellStyle: React.CSSProperties = {
	padding: "16px 20px",
	fontFamily: VREKO_FONT_MONO,
	fontSize: "12px",
	lineHeight: 1.8,
	color: VREKO_COLORS.green,
	whiteSpace: "pre-wrap",
};

export function TerminalBlock({ children, cursor = false }: TerminalBlockProps) {
	return (
		<Section style={wrapStyle}>
			<Text style={cellStyle}>
				{children}
				{cursor ? <span style={{ color: VREKO_COLORS.green }}>_</span> : null}
			</Text>
		</Section>
	);
}

export default TerminalBlock;
