import { Section, Text } from "@react-email/components";
import { emailTheme } from "../../theme";

export interface StatRowProps {
	label: string;
	value: string | number;
	unit?: string;
	icon?: string;
}

/**
 * StatRow - Display metrics in a terminal-style format
 */
export function StatRow({ label, value, unit, icon }: StatRowProps) {
	return (
		<Section
			style={{
				borderBottom: `${emailTheme.borderWidth} solid ${emailTheme.colors.divider}`,
				padding: `${emailTheme.spacing.sm} 0`,
			}}
		>
			<table width="100%" style={{ width: "100%" }}>
				<tr>
					<td style={{ width: "50%", verticalAlign: "middle" }}>
						<Text
							style={{
								margin: 0,
								fontSize: emailTheme.fontSizes.sm,
								color: emailTheme.colors.textSecondary,
								fontFamily: emailTheme.fonts.mono,
							}}
						>
							{icon && <span style={{ marginRight: "8px" }}>{icon}</span>}
							{label}
						</Text>
					</td>
					<td
						style={{
							width: "50%",
							textAlign: "right",
							verticalAlign: "middle",
						}}
					>
						<Text
							style={{
								margin: 0,
								fontSize: emailTheme.fontSizes.lg,
								color: emailTheme.colors.primary,
								fontFamily: emailTheme.fonts.mono,
								fontWeight: 600,
							}}
						>
							{value}
							{unit && (
								<span
									style={{
										fontSize: emailTheme.fontSizes.sm,
										color: emailTheme.colors.textMuted,
										marginLeft: emailTheme.spacing.xs,
									}}
								>
									{unit}
								</span>
							)}
						</Text>
					</td>
				</tr>
			</table>
		</Section>
	);
}
