import { Text } from "@react-email/components";
import { AlertBox, CodeBlock, PrimaryButton, RepoFooter, TerminalHeader, VrekoLayout } from "../../components";
import type { ResetPasswordContext } from "../../contexts";
import { ResetPasswordContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function ResetPassword({ resetUrl, expiresInMinutes, requestedFrom }: ResetPasswordContext) {
	return (
		<VrekoLayout title="Reset your password" preheader="Reset your Vreko password">
			<TerminalHeader status="processing" />

			<Text style={{ fontSize: "18px", marginBottom: "24px", color: "#FAFAFA" }}>Reset Your Password</Text>

			<AlertBox type="warning">
				A password reset was requested for your Vreko account. If this wasn't you, please ignore this email.
			</AlertBox>

			<PrimaryButton href={resetUrl}>Reset Password</PrimaryButton>

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "16px" }}>
				This reset link expires in {expiresInMinutes} minutes.
			</Text>

			<Text
				style={{
					fontSize: "14px",
					marginTop: "32px",
					marginBottom: "8px",
					color: "#A1A1AA",
				}}
			>
				Request details:
			</Text>

			<CodeBlock
				code={`IP Address: ${requestedFrom.ipAddress}${requestedFrom.location ? `\nLocation: ${requestedFrom.location}` : ""}`}
			/>

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "24px" }}>
				If you didn't request a password reset, your account may be compromised. Please contact support
				immediately.
			</Text>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const ResetPasswordTemplate: EmailTemplate<ResetPasswordContext> = {
	id: "auth.reset-password",
	category: "authentication",
	subject: () => "Reset your Vreko password",
	component: ResetPassword,
	previewProps: {
		resetUrl: "https://vreko.dev/reset?token=def456",
		expiresInMinutes: 30,
		requestedFrom: {
			ipAddress: "192.168.1.1",
			location: "San Francisco, CA",
		},
	},
	schema: ResetPasswordContextSchema,
};
