import type { EmailCategory, EmailTemplate, EmailTemplateId } from "./types";

/**
 * Template Registry
 * Type-safe central registry for all email templates
 */

interface TemplateMetadata {
	id: EmailTemplateId;
	category: EmailCategory;
	description: string;
	previewUrl?: string;
}

class TemplateRegistry {
	// biome-ignore lint/suspicious/noExplicitAny: heterogeneous template contexts stored in a single map
	private templates = new Map<EmailTemplateId, EmailTemplate<any>>();

	/**
	 * Register a template
	 */
	register<TContext>(template: EmailTemplate<TContext>): void {
		if (this.templates.has(template.id)) {
			// intentionally empty
		}
		this.templates.set(template.id, template);
	}

	/**
	 * Get a template by ID
	 */
	// biome-ignore lint/suspicious/noExplicitAny: heterogeneous template contexts stored in a single map
	get<T extends EmailTemplateId>(id: T): EmailTemplate<any> | undefined {
		return this.templates.get(id);
	}

	/**
	 * Check if template exists
	 */
	has(id: EmailTemplateId): boolean {
		return this.templates.has(id);
	}

	/**
	 * List all registered templates
	 */
	list(): TemplateMetadata[] {
		return Array.from(this.templates.values()).map((template) => ({
			id: template.id,
			category: template.category,
			description: `${template.category} email template`,
			previewUrl: `/email/preview/${template.id}`,
		}));
	}

	/**
	 * List templates by category
	 */
	listByCategory(category: EmailCategory): TemplateMetadata[] {
		return this.list().filter((meta) => meta.category === category);
	}

	/**
	 * Validate template ID
	 */
	validate(id: EmailTemplateId): boolean {
		return this.has(id);
	}

	/**
	 * Get template count
	 */
	get size(): number {
		return this.templates.size;
	}
}

// Export singleton instance
export const templateRegistry = new TemplateRegistry();

// Re-export types for convenience
export type { EmailTemplate, EmailTemplateId, TemplateMetadata };

// ─── Template Registration ────────────────────────────────────────────────────

import { CohortInviteTemplate } from "./templates/product/CohortInvite";

templateRegistry.register(CohortInviteTemplate);
