import { Body, Container, Head, Html, Preview, Section } from "@react-email/components";
import type React from "react";
import { emailTheme } from "../../theme";

export interface VrekoLayoutProps {
	title: string;
	preheader?: string;
	children: React.ReactNode;
}

/**
 * VrekoLayout - Base email layout with dark mode support
 * Includes <meta name="color-scheme" content="light dark"> as specified
 */
export function VrekoLayout({ title, preheader, children }: VrekoLayoutProps) {
	return (
		<Html lang="en">
			<Head>
				<meta name="color-scheme" content="light dark" />
				<title>{title}</title>
				{preheader && <Preview>{preheader}</Preview>}
			</Head>
			<Body
				style={{
					backgroundColor: emailTheme.colors.background,
					fontFamily: emailTheme.fonts.body,
					margin: 0,
					padding: 0,
				}}
			>
				<Container
					style={{
						maxWidth: emailTheme.maxWidth,
						margin: "0 auto",
						padding: emailTheme.spacing["2xl"],
					}}
				>
					<Section>{children}</Section>
				</Container>
			</Body>
		</Html>
	);
}
