import { Text } from "@react-email/components";
import { AlertBox, PrimaryButton, RepoFooter, TerminalHeader, VrekoLayout } from "../../components";
import type { VerifyEmailContext } from "../../contexts";
import { VerifyEmailContextSchema } from "../../contexts";
import type { EmailTemplate } from "../../types";

export function VerifyEmail({ verificationUrl, expiresInMinutes }: VerifyEmailContext) {
	return (
		<VrekoLayout title="Verify your email" preheader="Click to verify your Vreko account">
			<TerminalHeader status="online" />

			<Text style={{ fontSize: "18px", marginBottom: "24px", color: "#FAFAFA" }}>Welcome to Vreko!</Text>

			<AlertBox type="info">
				Please verify your email address to activate your account and start using Vreko.
			</AlertBox>

			<PrimaryButton href={verificationUrl}>Verify Email Address</PrimaryButton>

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "16px" }}>
				This verification link expires in {expiresInMinutes} minutes.
			</Text>

			<Text style={{ color: "#71717A", fontSize: "14px", marginTop: "24px" }}>
				If you didn't create a Vreko account, you can safely ignore this email.
			</Text>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const VerifyEmailTemplate: EmailTemplate<VerifyEmailContext> = {
	id: "auth.verify-email",
	category: "authentication",
	subject: () => "Verify your Vreko account",
	component: VerifyEmail,
	previewProps: {
		verificationUrl: "https://vreko.dev/verify?token=abc123",
		expiresInMinutes: 15,
	},
	schema: VerifyEmailContextSchema,
};
