import { Heading, Section, Text } from "@react-email/components";
import { RepoFooter } from "../../components/layouts/RepoFooter";
import { VrekoLayout } from "../../components/layouts/SnapBackLayout";
import { TerminalHeader } from "../../components/layouts/TerminalHeader";
import { PrimaryButton } from "../../components/primitives/PrimaryButton";
import { emailTheme } from "../../theme";
import type { EmailTemplate } from "../../types";

export interface PaymentFailedContext {
	amount: number;
	currency: string;
	retryDate: string;
}

export function PaymentFailed({ amount, currency, retryDate }: PaymentFailedContext) {
	const formattedAmount = new Intl.NumberFormat("en-US", {
		style: "currency",
		currency: currency.toUpperCase(),
	}).format(amount);

	const formattedDate = new Date(retryDate).toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
	});

	return (
		<VrekoLayout
			title="Your Vreko payment didn't go through"
			preheader="Update your payment method to keep Pro features active"
		>
			<TerminalHeader status="online" />

			<Section style={{ padding: "32px 24px" }}>
				<Heading
					style={{
						margin: "0 0 24px 0",
						fontSize: "20px",
						fontWeight: "500",
						color: emailTheme.colors.text,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					Your Vreko payment didn't go through
				</Heading>

				<Text
					style={{
						margin: "0 0 16px 0",
						fontSize: "16px",
						lineHeight: "24px",
						color: emailTheme.colors.textSecondary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					Your card on file couldn't be charged ({formattedAmount}). Update it to keep your Pro features
					active.
				</Text>

				<Section
					style={{
						margin: "24px 0",
						padding: "20px",
						backgroundColor: emailTheme.colors.surfaceSubtle,
						borderRadius: "8px",
						border: `1px solid ${emailTheme.colors.border}`,
					}}
				>
					<Text
						style={{
							margin: "0 0 8px 0",
							fontSize: "14px",
							color: emailTheme.colors.textTertiary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Next retry attempt
					</Text>
					<Text
						style={{
							margin: "0",
							fontSize: "18px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						{formattedDate}
					</Text>
				</Section>

				<Text
					style={{
						margin: "24px 0 16px 0",
						fontSize: "14px",
						lineHeight: "22px",
						color: emailTheme.colors.textTertiary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					No charges will be attempted until you update your payment method.
				</Text>

				<PrimaryButton href="https://console.vreko.dev/billing">Update Payment Method</PrimaryButton>
			</Section>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const PaymentFailedTemplate: EmailTemplate<PaymentFailedContext> = {
	id: "triage.payment-failed",
	category: "triage",
	subject: () => "Your Vreko payment didn't go through",
	component: PaymentFailed,
	previewProps: {
		amount: 29.0,
		currency: "USD",
		retryDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
	},
};
