// ESM imports fixed for Node.js v22+
import { logger } from "@vreko/infrastructure";
import { getHubSpotClient } from "../provider/hubspot/index.js";
import { createHubSpotContact, updateHubSpotContact } from "./contacts.js";
/**
 * Sync a Vreko user to HubSpot
 * Creates a new contact or updates existing one based on email
 *
 * @param userData - User data to sync
 * @returns HubSpot contact ID
 */
export async function syncUserToHubSpot(userData) {
    logger.info("Syncing user to HubSpot", { email: userData.email });
    const properties = mapUserDataToHubSpotProperties(userData);
    try {
        // Try to find existing contact by email
        const existingContact = await findContactByEmail(userData.email);
        if (existingContact?.id) {
            // Update existing contact
            const updated = await updateHubSpotContact({
                id: existingContact.id,
                properties,
            });
            logger.info("Updated existing HubSpot contact", {
                id: updated.id,
                email: userData.email,
            });
            return updated.id;
        }
        // Create new contact
        const created = await createHubSpotContact({ properties });
        logger.info("Created new HubSpot contact", {
            id: created.id,
            email: userData.email,
        });
        return created.id;
    }
    catch (error) {
        logger.error("Failed to sync user to HubSpot", {
            error,
            email: userData.email,
        });
        throw error;
    }
}
/**
 * Find a contact by email address
 */
export async function findContactByEmail(email) {
    try {
        const client = getHubSpotClient();
        const response = await client.crm.contacts.searchApi.doSearch({
            filterGroups: [
                {
                    filters: [
                        {
                            propertyName: "email",
                            // @ts-expect-error - HubSpot SDK type definitions may not match actual API
                            operator: "EQ",
                            value: email,
                        },
                    ],
                },
            ],
            properties: ["email", "firstname", "lastname", "vreko_user_id"],
            limit: 1,
        });
        if (response.results && response.results.length > 0) {
            const result = response.results[0];
            return {
                id: result.id,
                ...result.properties,
            };
        }
        return null;
    }
    catch (_error) {
        logger.warn("Contact not found by email", { email });
        return null;
    }
}
/**
 * Update contact properties in HubSpot
 */
export async function updateContactProperties(contactId, properties) {
    try {
        await updateHubSpotContact({
            id: contactId,
            properties: properties,
        });
        logger.info("Updated HubSpot contact properties", {
            contactId,
            propertyCount: Object.keys(properties).length,
        });
    }
    catch (error) {
        logger.error("Failed to update HubSpot contact properties", {
            error,
            contactId,
        });
        throw error;
    }
}
/**
 * Sync extension installation to HubSpot
 */
export async function syncExtensionInstalled(email, version, installDate = new Date()) {
    const contact = await findContactByEmail(email);
    if (!contact?.id) {
        logger.warn("Cannot sync extension install - contact not found", { email });
        return;
    }
    await updateContactProperties(contact.id, {
        extension_installed: true,
        extension_version: version,
        extension_install_date: installDate.getTime(),
    });
}
/**
 * Sync pioneer program update to HubSpot
 */
export async function syncPioneerUpdate(email, tier, points) {
    const contact = await findContactByEmail(email);
    if (!contact?.id) {
        logger.warn("Cannot sync pioneer update - contact not found", { email });
        return;
    }
    await updateContactProperties(contact.id, {
        pioneer_tier: tier,
        pioneer_points: points,
    });
}
