// ESM imports fixed for Node.js v22+
import { logger } from "@vreko/infrastructure";
import { combinedSchema, createTierUpgradeSagaWithDeps, db, EntitlementsServiceImpl, SagaOrchestratorImpl, sagaPersistence, } from "@vreko/platform";
import { and, eq } from "drizzle-orm";
import Stripe from "stripe";
import { BillingEmailHandler, emailService } from "../../../email/index.js";
const { subscriptions, webhookEvents, user } = combinedSchema;
let stripeClient = null;
// Singleton for cache invalidation (Gap 1 - Entitlements Integration)
const entitlementsService = new EntitlementsServiceImpl();
// Singleton for billing email notifications (P0.2 - Dunning emails)
const billingEmailHandler = new BillingEmailHandler(emailService);
// Cache environment variables at module level for performance
const PRICE_ID_MAP = {
    pro: process.env.STRIPE_PRO_MONTHLY_PRICE_ID,
    team: process.env.STRIPE_TEAM_MONTHLY_PRICE_ID,
    enterprise: process.env.STRIPE_ENTERPRISE_MONTHLY_PRICE_ID,
};
// Tier order for upgrade/downgrade detection
const TIER_ORDER = { free: 0, pro: 1, team: 2, enterprise: 3 };
/**
 * Trigger tier upgrade saga - extracted for testability
 * Fire-and-forget: doesn't block caller, handles errors internally
 */
function triggerTierUpgradeSaga(params) {
    const { userId, fromTier, toTier, subscriptionId, billingCycle, dbClient } = params;
    // Fire and forget - don't block webhook response
    void (async () => {
        try {
            const sagaOrchestrator = new SagaOrchestratorImpl(sagaPersistence);
            const sagaDef = createTierUpgradeSagaWithDeps({
            // Dependencies will be injected by the saga executor
            });
            // Register the saga definition
            sagaOrchestrator.registerSaga(sagaDef);
            // Look up user email for confirmation (protected lookup)
            let userEmail = "";
            let userName = null;
            try {
                const userRecord = await dbClient
                    .select({ email: user.email, name: user.name })
                    .from(user)
                    .where(eq(user.id, userId))
                    .limit(1);
                userEmail = userRecord[0]?.email ?? "";
                userName = userRecord[0]?.name ?? null;
            }
            catch (lookupError) {
                logger.warn("Failed to lookup user for saga, continuing without email", {
                    userId,
                    error: lookupError instanceof Error ? lookupError.message : String(lookupError),
                });
                // Continue saga without email - graceful degradation
            }
            // Inject Stripe client into saga context
            const stripe = getStripeClient();
            await sagaOrchestrator.start("tier_upgrade", {
                userId,
                fromTier: fromTier,
                toTier: toTier,
                subscriptionId,
                paymentProvider: "stripe",
                userEmail,
                userName,
                billingCycle,
                stripeClient: stripe, // Inject Stripe client for subscription updates
            });
            logger.info("Tier upgrade saga started", {
                userId,
                fromTier,
                toTier,
                subscriptionId,
                billingCycle,
            });
        }
        catch (sagaError) {
            logger.error("Failed to start tier upgrade saga", {
                userId,
                error: sagaError instanceof Error ? sagaError.message : String(sagaError),
            });
            // Don't fail the webhook - saga can be recovered by recovery service
        }
    })();
}
export function getStripeClient() {
    if (stripeClient) {
        return stripeClient;
    }
    const stripeSecretKey = process.env.STRIPE_SECRET_KEY;
    if (!stripeSecretKey) {
        throw new Error("Missing env variable STRIPE_SECRET_KEY");
    }
    stripeClient = new Stripe(stripeSecretKey);
    return stripeClient;
}
export const createCheckoutLink = async (options) => {
    const stripeClient = getStripeClient();
    const { type, productId, redirectUrl, customerId, organizationId, userId, trialPeriodDays, seats, email, pioneerCouponId, } = options;
    const metadata = {
        organization_id: organizationId || null,
        user_id: userId || null,
    };
    const response = await stripeClient.checkout.sessions.create({
        mode: type === "subscription" ? "subscription" : "payment",
        success_url: redirectUrl ?? "",
        line_items: [
            {
                quantity: seats ?? 1,
                price: productId,
            },
        ],
        ...(customerId ? { customer: customerId } : { customer_email: email }),
        ...(type === "one-time"
            ? {
                payment_intent_data: {
                    metadata,
                },
                customer_creation: "always",
            }
            : {
                subscription_data: {
                    metadata,
                    trial_period_days: trialPeriodDays,
                },
            }),
        ...(pioneerCouponId ? { discounts: [{ coupon: pioneerCouponId }] } : {}),
        metadata,
    });
    return response.url;
};
export const createCustomerPortalLink = async (options) => {
    const stripeClient = getStripeClient();
    const response = await stripeClient.billingPortal.sessions.create({
        customer: options.customerId,
        return_url: options.redirectUrl ?? "",
    });
    return response.url;
};
export const setSubscriptionSeats = async (options) => {
    const stripeClient = getStripeClient();
    const subscription = await stripeClient.subscriptions.retrieve(options.id);
    if (!subscription) {
        throw new Error("Subscription not found.");
    }
    await stripeClient.subscriptions.update(options.id, {
        items: [
            {
                id: subscription.items.data[0].id,
                quantity: options.seats,
            },
        ],
    });
};
export const cancelSubscription = async (id) => {
    const stripeClient = getStripeClient();
    await stripeClient.subscriptions.cancel(id);
};
// =============================================================================
// Idempotency Helpers
// =============================================================================
/**
 * Check if a webhook event has already been processed.
 * Uses Stripe's event.id as the unique identifier.
 *
 * @see https://docs.stripe.com/webhooks#handle-duplicate-events
 */
async function isEventAlreadyProcessed(eventId) {
    if (!db) {
        return false;
    }
    const existing = await db.query.webhookEvents.findFirst({
        where: and(eq(webhookEvents.sourceId, eventId), eq(webhookEvents.source, "stripe"), eq(webhookEvents.processed, true)),
    });
    return !!existing;
}
/**
 * Record a webhook event for idempotency tracking.
 * Called after successful processing to prevent duplicates.
 */
async function recordProcessedEvent(eventId, eventType, payload, error) {
    if (!db) {
        return;
    }
    try {
        // Use upsert pattern to handle race conditions
        const existing = await db.query.webhookEvents.findFirst({
            where: and(eq(webhookEvents.sourceId, eventId), eq(webhookEvents.source, "stripe")),
        });
        if (existing) {
            await db
                .update(webhookEvents)
                .set({
                processed: !error,
                processedAt: new Date(),
                errorMessage: error ?? null,
                retryCount: (existing.retryCount ?? 0) + 1,
            })
                .where(eq(webhookEvents.id, existing.id));
        }
        else {
            await db.insert(webhookEvents).values({
                id: Date.now(), // Simple bigint ID
                eventId: eventId,
                eventType: eventType,
                source: "stripe",
                sourceId: eventId,
                payload: payload,
                processed: !error,
                processedAt: new Date(),
                errorMessage: error ?? null,
                retryCount: 0,
            });
        }
    }
    catch (err) {
        // Don't fail the webhook if we can't record - log and continue
        logger.error("Failed to record webhook event", { eventId, error: err });
    }
}
// =============================================================================
// Webhook Handler
// =============================================================================
export const webhookHandler = async (req) => {
    const stripeClient = getStripeClient();
    // Validate request body exists
    if (!req.body) {
        return new Response("Invalid request.", { status: 400 });
    }
    // Validate webhook secret is configured
    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
    if (!webhookSecret) {
        logger.error("STRIPE_WEBHOOK_SECRET not configured");
        return new Response("Webhook not configured.", { status: 500 });
    }
    let event;
    // Step 1: Verify webhook signature (must happen within 5 minutes of delivery)
    try {
        const body = await req.text();
        const signature = req.headers.get("stripe-signature");
        if (!signature) {
            logger.error("Missing stripe-signature header");
            return new Response("Missing signature.", { status: 400 });
        }
        event = await stripeClient.webhooks.constructEventAsync(body, signature, webhookSecret);
    }
    catch (e) {
        logger.error("Failed to verify Stripe webhook signature", { error: e });
        return new Response("Invalid signature.", { status: 400 });
    }
    // Step 2: Check idempotency - skip if already processed
    const alreadyProcessed = await isEventAlreadyProcessed(event.id);
    if (alreadyProcessed) {
        logger.debug("Webhook event already processed, skipping", { eventId: event.id, eventType: event.type });
        return new Response("Already processed.", { status: 200 });
    }
    // Step 3: Validate metadata for events that require it
    if (event.type === "customer.subscription.created" || event.type === "customer.subscription.updated") {
        const objWithMetadata = event.data.object;
        if (!objWithMetadata.metadata) {
            logger.error("Missing metadata in subscription webhook", { eventType: event.type, eventId: event.id });
            // Still return 200 to prevent retries for malformed events
            await recordProcessedEvent(event.id, event.type, event.data.object, "Missing metadata");
            return new Response("Missing metadata.", { status: 200 });
        }
        const { user_id, organization_id } = objWithMetadata.metadata;
        if (!user_id && !organization_id) {
            logger.error("Missing user_id or organization_id in metadata", {
                eventType: event.type,
                eventId: event.id,
                metadata: objWithMetadata.metadata,
            });
            await recordProcessedEvent(event.id, event.type, event.data.object, "Missing user_id or organization_id");
            return new Response("Missing user/org in metadata.", { status: 200 });
        }
    }
    // Step 4: Process the event
    let processingError;
    try {
        switch (event.type) {
            case "checkout.session.completed": {
                await handleCheckoutSessionCompleted(event, stripeClient);
                break;
            }
            case "customer.subscription.created":
            case "customer.subscription.updated": {
                await handleSubscriptionCreatedOrUpdated(event);
                break;
            }
            case "customer.subscription.deleted": {
                await handleSubscriptionDeleted(event);
                break;
            }
            case "invoice.payment_succeeded": {
                await handlePaymentSucceeded(event);
                break;
            }
            case "invoice.payment_failed": {
                await handlePaymentFailed(event);
                break;
            }
            default:
                logger.debug("Unhandled event type", { eventType: event.type, eventId: event.id });
        }
    }
    catch (error) {
        processingError = error instanceof Error ? error.message : "Unknown error";
        logger.error("Error processing webhook", {
            eventId: event.id,
            eventType: event.type,
            error,
        });
    }
    // Step 5: Record the event for idempotency tracking
    await recordProcessedEvent(event.id, event.type, event.data.object, processingError);
    // Always return 200 to prevent Stripe from retrying
    // Errors are logged and can be investigated via the webhookEvents table
    return new Response("OK", { status: 200 });
};
// =============================================================================
// Event Handlers
// =============================================================================
async function handleCheckoutSessionCompleted(event, stripeClient) {
    const session = event.data.object;
    if (session.mode !== "subscription") {
        // Handle one-time payment
        const checkoutSession = await stripeClient.checkout.sessions.retrieve(session.id, {
            expand: ["line_items"],
        });
        const productId = checkoutSession.line_items?.data[0]?.price?.id;
        if (!productId) {
            logger.error("Missing product ID in checkout session", { sessionId: session.id });
            return;
        }
        // One-time payment handling - currently stub
        logger.info("One-time payment completed", {
            sessionId: session.id,
            productId,
            customerId: session.customer,
        });
    }
    // Subscription mode is handled by customer.subscription.created
}
async function handleSubscriptionCreatedOrUpdated(event) {
    if (!db) {
        throw new Error("Database not available");
    }
    const subscription = event.data.object;
    const metadata = subscription.metadata;
    const userId = metadata?.user_id || null;
    const organizationId = metadata?.organization_id || null;
    // Safety check - this should be caught earlier but double-check
    if (!userId && !organizationId) {
        throw new Error("Missing user_id or organization_id in subscription metadata");
    }
    const dbClient = db;
    const subscriptionItem = subscription.items.data[0];
    // Safely extract price ID
    const priceId = subscriptionItem?.price?.id;
    const plan = priceId ? mapPriceIdToPlan(priceId) : "free";
    const status = mapStripeStatusToSubscriptionStatus(subscription.status);
    // Get period dates from subscription item (Stripe API v2024+)
    const currentPeriodStart = subscriptionItem?.current_period_start;
    const currentPeriodEnd = subscriptionItem?.current_period_end;
    // Safely extract customer ID (can be string or expanded object)
    const customerId = typeof subscription.customer === "string" ? subscription.customer : subscription.customer.id;
    // Use atomic transaction result to prevent race conditions
    const txResult = await dbClient.transaction(async (tx) => {
        // Check if subscription already exists (handles race conditions)
        const existing = await tx.query.subscriptions.findFirst({
            where: eq(subscriptions.stripeSubscriptionId, subscription.id),
        });
        const subscriptionData = {
            stripeSubscriptionId: subscription.id,
            stripeCustomerId: customerId,
            userId,
            organizationId,
            plan,
            status,
            currentPeriodStart: currentPeriodStart ? new Date(currentPeriodStart * 1000) : null,
            currentPeriodEnd: currentPeriodEnd ? new Date(currentPeriodEnd * 1000) : null,
            cancelAtPeriodEnd: subscription.cancel_at_period_end,
            trialEnd: subscription.trial_end ? new Date(subscription.trial_end * 1000) : null,
            seats: subscriptionItem?.quantity ?? 1,
            metadata: subscription.metadata,
            updatedAt: new Date(),
        };
        if (existing) {
            // Update existing subscription
            await tx
                .update(subscriptions)
                .set(subscriptionData)
                .where(eq(subscriptions.stripeSubscriptionId, subscription.id));
            logger.info("Subscription updated", {
                subscriptionId: subscription.id,
                plan,
                status,
                userId,
                organizationId,
            });
        }
        else {
            // Create new subscription
            await tx.insert(subscriptions).values(subscriptionData);
            logger.info("Subscription created", {
                subscriptionId: subscription.id,
                plan,
                status,
                userId,
                organizationId,
            });
        }
        // Return atomic result for saga trigger (prevents race condition)
        return {
            previousPlan: existing?.plan ?? null,
            currentPlan: plan,
            isNewSubscription: !existing,
        };
    });
    // Invalidate entitlements cache after subscription change (Gap 1 - Cache Invalidation)
    if (userId) {
        try {
            await entitlementsService.invalidateCache(userId);
            logger.debug("Entitlements cache invalidated for user", { userId });
        }
        catch (err) {
            logger.error("Failed to invalidate entitlements cache", { userId, error: err });
        }
    }
    // Trigger tier upgrade saga if plan changed (Gap 3 - Saga Integration)
    // Use atomic txResult to prevent race conditions (not external variable)
    if (userId && txResult.previousPlan && !txResult.isNewSubscription) {
        const previousPlan = txResult.previousPlan;
        const currentPlan = txResult.currentPlan;
        // Check for upgrade vs downgrade using module-level tier order
        const previousTierLevel = TIER_ORDER[previousPlan] ?? 0;
        const currentTierLevel = TIER_ORDER[currentPlan] ?? 0;
        const isUpgrade = currentTierLevel > previousTierLevel;
        if (previousPlan !== currentPlan && isUpgrade) {
            // Extract billing cycle (supports monthly/annual)
            const interval = subscription.items.data[0]?.price?.recurring?.interval;
            const billingCycle = interval === "year" ? "year" : "month";
            // Trigger saga via extracted function (fire-and-forget)
            triggerTierUpgradeSaga({
                userId,
                fromTier: previousPlan,
                toTier: currentPlan,
                subscriptionId: subscription.id,
                billingCycle,
                dbClient,
            });
        }
        else if (previousPlan !== currentPlan && !isUpgrade) {
            // Log downgrade for observability (separate handling could be added)
            logger.info("Subscription downgraded", {
                userId,
                fromTier: previousPlan,
                toTier: currentPlan,
                subscriptionId: subscription.id,
            });
        }
    }
}
async function handleSubscriptionDeleted(event) {
    if (!db) {
        throw new Error("Database not available");
    }
    const subscription = event.data.object;
    const dbClient = db;
    await dbClient.transaction(async (tx) => {
        const [updated] = await tx
            .update(subscriptions)
            .set({
            status: "canceled",
            cancelAtPeriodEnd: true,
            updatedAt: new Date(),
        })
            .where(eq(subscriptions.stripeSubscriptionId, subscription.id))
            .returning();
        if (updated) {
            logger.info("Subscription canceled", {
                subscriptionId: subscription.id,
                userId: updated.userId,
                organizationId: updated.organizationId,
            });
            // Invalidate entitlements cache after subscription cancellation (Gap 1 - Cache Invalidation)
            if (updated.userId) {
                try {
                    await entitlementsService.invalidateCache(updated.userId);
                    logger.debug("Entitlements cache invalidated for user", { userId: updated.userId });
                }
                catch (err) {
                    logger.error("Failed to invalidate entitlements cache", { userId: updated.userId, error: err });
                }
            }
        }
        else {
            // Subscription not found - might have been deleted directly or never created
            logger.warn("Subscription not found for deletion", { subscriptionId: subscription.id });
        }
    });
}
async function handlePaymentSucceeded(event) {
    const invoice = event.data.object;
    // Extract subscription ID from parent.subscription_details (Stripe API v2024+)
    const subscriptionRef = invoice.parent?.subscription_details?.subscription;
    const subscriptionId = subscriptionRef
        ? typeof subscriptionRef === "string"
            ? subscriptionRef
            : subscriptionRef.id
        : null;
    // Update subscription status to active if it was past_due
    let userId = null;
    if (db && subscriptionId) {
        const dbClient = db;
        const [updated] = await dbClient
            .update(subscriptions)
            .set({
            status: "active",
            updatedAt: new Date(),
        })
            .where(and(eq(subscriptions.stripeSubscriptionId, subscriptionId), eq(subscriptions.status, "past_due")))
            .returning();
        if (updated) {
            userId = updated.userId;
        }
    }
    // Invalidate entitlements cache after payment recovery (Gap 1 - Cache Invalidation)
    if (userId) {
        try {
            await entitlementsService.invalidateCache(userId);
            logger.debug("Entitlements cache invalidated for user", { userId });
        }
        catch (err) {
            logger.error("Failed to invalidate entitlements cache", { userId, error: err });
        }
    }
    logger.info("Payment succeeded", {
        invoiceId: invoice.id,
        customerId: invoice.customer,
        subscriptionId,
        amountPaid: invoice.amount_paid,
    });
}
async function handlePaymentFailed(event) {
    const invoice = event.data.object;
    // Extract subscription ID from parent.subscription_details (Stripe API v2024+)
    const subscriptionRef = invoice.parent?.subscription_details?.subscription;
    const subscriptionId = subscriptionRef
        ? typeof subscriptionRef === "string"
            ? subscriptionRef
            : subscriptionRef.id
        : null;
    // Update subscription status to past_due
    if (db && subscriptionId) {
        const dbClient = db;
        const [updated] = await dbClient
            .update(subscriptions)
            .set({
            status: "past_due",
            updatedAt: new Date(),
        })
            .where(eq(subscriptions.stripeSubscriptionId, subscriptionId))
            .returning();
        if (updated) {
            logger.warn("Payment failed - subscription marked past_due", {
                invoiceId: invoice.id,
                subscriptionId,
                userId: updated.userId,
                organizationId: updated.organizationId,
            });
            // Invalidate entitlements cache after payment failure (Gap 1 - Cache Invalidation)
            if (updated.userId) {
                try {
                    await entitlementsService.invalidateCache(updated.userId);
                    logger.debug("Entitlements cache invalidated for user", { userId: updated.userId });
                }
                catch (err) {
                    logger.error("Failed to invalidate entitlements cache", { userId: updated.userId, error: err });
                }
                // Send dunning email (P0.2 - Payment failed notification)
                try {
                    const userRecord = await dbClient
                        .select({ email: user.email })
                        .from(user)
                        .where(eq(user.id, updated.userId))
                        .limit(1);
                    if (userRecord[0]?.email) {
                        // Stripe typically retries after 3 days
                        const retryDate = new Date();
                        retryDate.setDate(retryDate.getDate() + 3);
                        const appUrl = process.env.BETTER_AUTH_URL || process.env.AUTH_URL || "https://vreko.dev";
                        await billingEmailHandler.sendPaymentFailed({
                            to: userRecord[0].email,
                            userId: updated.userId,
                            planName: updated.plan || "Pro",
                            amount: invoice.amount_due / 100, // Convert from cents
                            currency: invoice.currency?.toUpperCase() || "USD",
                            retryDate,
                            updatePaymentUrl: `${appUrl}/app/billing?action=update-payment`,
                        });
                        logger.info("Dunning email sent for payment failure", {
                            userId: updated.userId,
                            invoiceId: invoice.id,
                        });
                    }
                }
                catch (emailErr) {
                    // Don't fail the webhook if email fails - log and continue
                    logger.error("Failed to send dunning email", {
                        userId: updated.userId,
                        error: emailErr instanceof Error ? emailErr.message : String(emailErr),
                    });
                }
            }
        }
    }
    else {
        logger.warn("Payment failed", {
            invoiceId: invoice.id,
            customerId: invoice.customer,
        });
    }
}
// =============================================================================
// Helper Functions
// =============================================================================
/**
 * Map Stripe price IDs to plan names.
 * Uses cached environment variables for performance.
 */
export function mapPriceIdToPlan(priceId) {
    if (priceId === PRICE_ID_MAP.pro) {
        return "pro";
    }
    if (priceId === PRICE_ID_MAP.team) {
        return "team";
    }
    if (priceId === PRICE_ID_MAP.enterprise) {
        return "enterprise";
    }
    logger.warn(`Unknown price ID: ${priceId}, defaulting to free`);
    return "free";
}
/**
 * Map Stripe subscription status to our status enum.
 * Handles all Stripe status values including edge cases.
 *
 * @see https://docs.stripe.com/api/subscriptions/object#subscription_object-status
 */
export function mapStripeStatusToSubscriptionStatus(stripeStatus) {
    switch (stripeStatus) {
        case "active":
            return "active";
        case "canceled":
            return "canceled";
        case "past_due":
            return "past_due";
        case "trialing":
            return "trialing";
        case "paused":
            return "paused";
        case "incomplete":
        case "incomplete_expired":
        case "unpaid":
            // Map payment-related issues to past_due for visibility
            return "past_due";
        default:
            // TypeScript exhaustiveness check - this should never happen
            logger.warn(`Unknown Stripe status: ${stripeStatus}, defaulting to active`);
            return "active";
    }
}
