import { Heading, Section, Text } from "@react-email/components";
import { emailTheme } from "../../theme";

export interface TerminalHeaderProps {
	status?: "online" | "processing" | "offline" | "critical" | "degraded";
}

/**
 * TerminalHeader - Logo with terminal-style status indicator
 */
export function TerminalHeader({ status = "online" }: TerminalHeaderProps) {
	const statusColors = {
		online: emailTheme.colors.success,
		processing: emailTheme.colors.warning,
		offline: emailTheme.colors.textMuted,
		critical: emailTheme.colors.error,
		degraded: emailTheme.colors.warning,
	};

	const statusText = {
		online: "● CONNECTED",
		processing: "○ PROCESSING",
		offline: "○ OFFLINE",
		critical: "● CRITICAL",
		degraded: "○ DEGRADED",
	};

	return (
		<Section
			style={{
				borderBottom: `${emailTheme.borderWidth} solid ${emailTheme.colors.border}`,
				paddingBottom: emailTheme.spacing.lg,
				marginBottom: emailTheme.spacing.xl,
			}}
		>
			<table width="100%" style={{ width: "100%" }}>
				<tr>
					<td style={{ verticalAlign: "middle" }}>
						<Heading
							style={{
								margin: 0,
								fontSize: emailTheme.fontSizes["2xl"],
								fontWeight: 600,
								color: emailTheme.colors.text,
								fontFamily: emailTheme.fonts.mono,
							}}
						>
							<span style={{ color: emailTheme.colors.primary }}>$</span> Vreko
						</Heading>
					</td>
					<td
						style={{
							textAlign: "right",
							verticalAlign: "middle",
						}}
					>
						<Text
							style={{
								margin: 0,
								fontSize: emailTheme.fontSizes.xs,
								color: statusColors[status],
								fontFamily: emailTheme.fonts.mono,
								letterSpacing: "0.5px",
							}}
						>
							{statusText[status]}
						</Text>
					</td>
				</tr>
			</table>
		</Section>
	);
}
