import { Heading, Section, Text } from "@react-email/components";
import { RepoFooter } from "../../components/layouts/RepoFooter";
import { VrekoLayout } from "../../components/layouts/SnapBackLayout";
import { TerminalHeader } from "../../components/layouts/TerminalHeader";
import { PrimaryButton } from "../../components/primitives/PrimaryButton";
import { emailTheme } from "../../theme";
import type { EmailTemplate } from "../../types";

export interface IssueResolvedContext {
	issueId: string;
	originalSubject: string;
	resolutionDescription?: string;
	changelogUrl?: string;
}

export function IssueResolved({ issueId, originalSubject, resolutionDescription, changelogUrl }: IssueResolvedContext) {
	return (
		<VrekoLayout title={`Re: ${originalSubject}`} preheader="Your issue has been resolved">
			<TerminalHeader status="online" />

			<Section style={{ padding: "32px 24px" }}>
				<Heading
					style={{
						margin: "0 0 24px 0",
						fontSize: "24px",
						fontWeight: "600",
						color: emailTheme.colors.success,
						fontFamily: emailTheme.fonts.mono,
					}}
				>
					Issue resolved
				</Heading>

				<Text
					style={{
						margin: "0 0 16px 0",
						fontSize: "16px",
						lineHeight: "24px",
						color: emailTheme.colors.textSecondary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					The issue you reported ( <strong style={{ color: emailTheme.colors.text }}>{issueId}</strong>) has
					been resolved.
				</Text>

				{resolutionDescription && (
					<Text
						style={{
							margin: "16px 0",
							fontSize: "14px",
							lineHeight: "20px",
							color: emailTheme.colors.textTertiary,
							fontFamily: emailTheme.fonts.sans,
							padding: "16px",
							backgroundColor: emailTheme.colors.surfaceSubtle,
							borderRadius: "8px",
						}}
					>
						{resolutionDescription}
					</Text>
				)}

				<Text
					style={{
						margin: "24px 0 16px 0",
						fontSize: "16px",
						lineHeight: "24px",
						color: emailTheme.colors.textSecondary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					Thanks for the report - this is exactly the kind of feedback that makes Vreko better for everyone.
				</Text>

				{changelogUrl && <PrimaryButton href={changelogUrl}>View Release Notes</PrimaryButton>}
			</Section>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const IssueResolvedTemplate: EmailTemplate<IssueResolvedContext> = {
	id: "triage.issue-resolved",
	category: "triage",
	subject: (ctx) => `Re: ${ctx.originalSubject}`,
	component: IssueResolved,
	previewProps: {
		issueId: "VRK-123",
		originalSubject: "Help with MCP configuration",
		resolutionDescription: "Fixed the MCP handshake timeout issue in the latest release.",
		changelogUrl: "https://vreko.dev/changelog",
	},
};
