import { Heading, Section, Text } from "@react-email/components";
import { RepoFooter } from "../../components/layouts/RepoFooter";
import { VrekoLayout } from "../../components/layouts/SnapBackLayout";
import { TerminalHeader } from "../../components/layouts/TerminalHeader";
import { CodeBlock } from "../../components/primitives/CodeBlock";
import { PrimaryButton } from "../../components/primitives/PrimaryButton";
import { emailTheme } from "../../theme";
import type { EmailTemplate } from "../../types";

export interface MCPTroubleshootContext {
	userName?: string;
}

export function MCPTroubleshoot({ userName }: MCPTroubleshootContext) {
	const greeting = userName ? `Hi ${userName}` : "Hi there";

	return (
		<VrekoLayout title="Your MCP connection didn't complete" preheader="Quick troubleshooting steps for MCP setup">
			<TerminalHeader status="online" />

			<Section style={{ padding: "32px 24px" }}>
				<Heading
					style={{
						margin: "0 0 24px 0",
						fontSize: "20px",
						fontWeight: "500",
						color: emailTheme.colors.text,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					{greeting},
				</Heading>

				<Text
					style={{
						margin: "0 0 16px 0",
						fontSize: "16px",
						lineHeight: "24px",
						color: emailTheme.colors.textSecondary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					Looks like your MCP connection didn't complete. Here are the most common fixes:
				</Text>

				<Section
					style={{
						margin: "24px 0",
						padding: "20px",
						backgroundColor: emailTheme.colors.surfaceSubtle,
						borderRadius: "8px",
						border: `1px solid ${emailTheme.colors.border}`,
					}}
				>
					<Text
						style={{
							margin: "0 0 12px 0",
							fontSize: "14px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						1. Check MCP Server Configuration
					</Text>
					<Text
						style={{
							margin: "0 0 20px 0",
							fontSize: "14px",
							lineHeight: "20px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Ensure your IDE has MCP support enabled in settings.
					</Text>

					<Text
						style={{
							margin: "0 0 12px 0",
							fontSize: "14px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						2. Verify API Key
					</Text>
					<CodeBlock code="$ vreko auth verify" />
					<Text
						style={{
							margin: "12px 0 20px 0",
							fontSize: "14px",
							lineHeight: "20px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Run this to check your API key is valid.
					</Text>

					<Text
						style={{
							margin: "0 0 12px 0",
							fontSize: "14px",
							fontWeight: "600",
							color: emailTheme.colors.text,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						3. Restart Your IDE
					</Text>
					<Text
						style={{
							margin: "0",
							fontSize: "14px",
							lineHeight: "20px",
							color: emailTheme.colors.textSecondary,
							fontFamily: emailTheme.fonts.sans,
						}}
					>
						Sometimes a simple restart refreshes the connection.
					</Text>
				</Section>

				<Text
					style={{
						margin: "24px 0 16px 0",
						fontSize: "14px",
						lineHeight: "22px",
						color: emailTheme.colors.textTertiary,
						fontFamily: emailTheme.fonts.sans,
					}}
				>
					Need more help? Reply to this email and we'll get you sorted.
				</Text>

				<PrimaryButton href="https://docs.vreko.dev/mcp">MCP Setup Guide</PrimaryButton>
			</Section>

			<RepoFooter />
		</VrekoLayout>
	);
}

export const MCPTroubleshootTemplate: EmailTemplate<MCPTroubleshootContext> = {
	id: "triage.mcp-troubleshoot",
	category: "triage",
	subject: () => "Your MCP connection didn't complete",
	component: MCPTroubleshoot,
	previewProps: {
		userName: "Alex",
	},
};
